const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Jaén, Spain (east of Córdoba)
  const jaen = ee.Geometry.Point([-3.79, 37.77]);
  const startDate = '2023-01-01';
  const endDate = '2023-05-15';

  // 2. Data Acquisition & Check
  const precipitation = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(jaen);

  const imageCount = precipitation.size().getInfo();
  console.log(`Images found: ${imageCount}`);

  if (imageCount === 0) {
    console.log("No precipitation data found for the period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum all precipitation
  const totalPrecip = precipitation.sum();

  // 4. Calculation
  const stats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: jaen,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const precipMm = stats.precipitation;

  // Check for valid pixels
  const pixelCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: jaen,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const validPixels = pixelCount.precipitation;

  console.log(`Valid pixels: ${validPixels}`);

  if (validPixels === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Validation & Final Answer
  if (precipMm === null || precipMm === undefined || isNaN(precipMm)) {
    console.log("Calculation returned invalid value.");
    console.log("<answer>C3</answer>");
    return;
  }

  const precipInches = precipMm / 25.4;
  const threshold = 3.0;

  console.log(`Total rainfall: ${precipMm.toFixed(2)} mm (${precipInches.toFixed(2)} inches)`);
  console.log(`Threshold: ${threshold} inches`);

  if (precipInches > threshold) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
